<template>
  <section class="page">
    <div class="page-heading"><div><p class="section-label">平台管理</p><h1>用户管理</h1></div><span class="scope-note">管理小程序用户账号状态</span></div>
    <form class="filter-panel" @submit.prevent="applyFilters">
      <label class="filter-field filter-keyword"><span>用户信息</span><input v-model.trim="filters.keyword" type="search" placeholder="昵称、用户名或手机号" /></label>
      <label class="filter-field"><span>账号状态</span><select v-model="filters.status"><option value="">全部状态</option><option value="1">已启用</option><option value="0">已禁用</option></select></label>
      <div class="filter-actions"><el-button class="ui-action primary-button" native-type="submit" type="primary" :icon="Search">查询</el-button><el-button class="ui-action secondary-button" native-type="button" @click="resetFilters">重置</el-button></div>
    </form>
    <section class="table-panel">
      <div class="table-heading"><h2>用户列表</h2><span v-if="!loading && !loadError" class="total-count">共 {{ total }} 项</span></div>
      <div v-if="actionMessage" class="action-message" :class="actionType">{{ actionMessage }}</div>
      <div v-if="loading" class="state-panel">正在加载用户...</div>
      <div v-else-if="loadError" class="state-panel state-error"><p>{{ loadError }}</p><el-button class="ui-action secondary-button" native-type="button" @click="loadUsers" :icon="Refresh">重新加载</el-button></div>
      <div v-else-if="users.length === 0" class="state-panel"><p>暂无符合条件的用户</p><el-button class="ui-action secondary-button" native-type="button" @click="resetFilters">清除筛选</el-button></div>
      <template v-else>
        <div class="table-scroll"><table><thead><tr><th>用户</th><th>用户名</th><th>手机号</th><th>状态</th><th>注册时间</th><th class="action-column">操作</th></tr></thead>
          <tbody><tr v-for="user in users" :key="user.id"><td><strong>{{ user.name || '未设置昵称' }}</strong></td><td>{{ user.username || '-' }}</td><td>{{ user.phone || '-' }}</td><td><span class="status" :class="user.status === 1 ? 'status-on' : 'status-off'">{{ user.status === 1 ? '已启用' : '已禁用' }}</span></td><td>{{ formatDate(user.createTime) }}</td><td class="action-column"><el-button class="ui-action link-button" native-type="button" @click="openDetail(user.id)" type="primary" link>查看</el-button><el-button class="ui-action link-button" :class="user.status === 1 ? 'danger-link' : ''" native-type="button" :disabled="statusUpdatingId === user.id" @click="toggleStatus(user)" type="primary" link :loading="statusUpdatingId === user.id">{{ statusUpdatingId === user.id ? '处理中' : user.status === 1 ? '禁用' : '启用' }}</el-button></td></tr></tbody>
        </table></div>
        <div class="pagination"><span>第 {{ page }} / {{ pageCount }} 页</span><el-pagination :current-page="page" :page-size="pageSize" :total="total" :pager-count="5" layout="prev, pager, next" :disabled="loading" @current-change="changePage" /></div>
      </template>
    </section>
    <div v-if="detailVisible" class="drawer-mask" @click.self="closeDetail"><aside class="drawer" role="dialog" aria-modal="true" aria-label="用户详情">
      <div class="drawer-heading"><div><p>小程序用户</p><h2>用户详情</h2></div><button class="close-button" type="button" aria-label="关闭详情" @click="closeDetail">×</button></div>
      <div v-if="detailLoading" class="state-panel">正在加载详情...</div><div v-else-if="detailError" class="state-panel state-error"><p>{{ detailError }}</p><el-button class="ui-action secondary-button" native-type="button" @click="loadDetail(detailId)" :icon="Refresh">重新加载</el-button></div>
      <template v-else-if="detailUser"><div class="user-summary"><span>{{ displayInitial(detailUser) }}</span><div><h3>{{ detailUser.name || '未设置昵称' }}</h3><p>{{ detailUser.username || '未设置用户名' }}</p></div></div><dl class="detail-list"><div><dt>用户编号</dt><dd>{{ detailUser.id }}</dd></div><div><dt>用户名</dt><dd>{{ detailUser.username || '-' }}</dd></div><div><dt>用户昵称</dt><dd>{{ detailUser.name || '-' }}</dd></div><div><dt>手机号</dt><dd>{{ detailUser.phone || '-' }}</dd></div><div><dt>账号状态</dt><dd>{{ detailUser.status === 1 ? '已启用' : '已禁用' }}</dd></div><div><dt>注册时间</dt><dd>{{ formatDate(detailUser.createTime) }}</dd></div><div><dt>更新时间</dt><dd>{{ formatDate(detailUser.updateTime) }}</dd></div></dl><div class="drawer-actions"><el-button class="ui-action secondary-button" native-type="button" @click="closeDetail">关闭</el-button><el-button class="ui-action primary-button" native-type="button" :disabled="statusUpdatingId === detailUser.id" @click="toggleStatus(detailUser)" type="primary" :loading="statusUpdatingId === detailUser.id">{{ detailUser.status === 1 ? '禁用账号' : '启用账号' }}</el-button></div></template>
    </aside></div>
  </section>
</template>

<script setup>
import { Search, Refresh } from '@element-plus/icons-vue'
import { computed, onMounted, reactive, ref } from 'vue'
import { getAdminUserApi, pageAdminUsersApi, updateAdminUserStatusApi } from '../api/adminUser.js'
const pageSize = 10
const page = ref(1), total = ref(0), users = ref([]), loading = ref(false), loadError = ref('')
const filters = reactive({ keyword: '', status: '' })
const actionMessage = ref(''), actionType = ref('success'), statusUpdatingId = ref(null)
const detailVisible = ref(false), detailLoading = ref(false), detailError = ref(''), detailUser = ref(null), detailId = ref(null)
const pageCount = computed(() => Math.max(1, Math.ceil(total.value / pageSize)))
function queryParams() { const params = { page: page.value, pageSize }; if (filters.keyword) params.keyword = filters.keyword; if (filters.status !== '') params.status = filters.status; return params }
async function loadUsers() { loading.value = true; loadError.value = ''; try { const response = await pageAdminUsersApi(queryParams()); if (response.data?.code !== 200) throw new Error(response.data?.message || '用户加载失败'); total.value = Number(response.data.data?.total || 0); users.value = response.data.data?.records || [] } catch (error) { users.value = []; total.value = 0; loadError.value = error.response?.data?.message || error.message || '用户加载失败，请稍后重试' } finally { loading.value = false } }
function applyFilters() { page.value = 1; loadUsers() }
function resetFilters() { filters.keyword = ''; filters.status = ''; page.value = 1; loadUsers() }
function changePage(next) { if (next >= 1 && next <= pageCount.value && next !== page.value) { page.value = next; loadUsers() } }
function showMessage(message, type = 'success') { actionMessage.value = message; actionType.value = type; window.setTimeout(() => { actionMessage.value = '' }, 3500) }
async function toggleStatus(user) { const nextStatus = user.status === 1 ? 0 : 1; if (nextStatus === 0 && !window.confirm(`确认禁用“${user.name || user.username || user.id}”吗？禁用后该用户将无法继续使用账号。`)) return; statusUpdatingId.value = user.id; try { const response = await updateAdminUserStatusApi(nextStatus, user.id); if (response.data?.code !== 200) throw new Error(response.data?.message || '状态更新失败'); showMessage(`用户已${nextStatus === 1 ? '启用' : '禁用'}`); detailVisible.value = false; await loadUsers() } catch (error) { showMessage(error.response?.data?.message || error.message || '状态更新失败，请稍后重试', 'error') } finally { statusUpdatingId.value = null } }
async function openDetail(id) { detailVisible.value = true; detailId.value = id; detailUser.value = null; await loadDetail(id) }
async function loadDetail(id) { detailLoading.value = true; detailError.value = ''; try { const response = await getAdminUserApi(id); if (response.data?.code !== 200) throw new Error(response.data?.message || '详情加载失败'); detailUser.value = response.data.data } catch (error) { detailError.value = error.response?.data?.message || error.message || '详情加载失败，请稍后重试' } finally { detailLoading.value = false } }
function closeDetail() { detailVisible.value = false }
function displayInitial(user) { return String(user.name || user.username || '用').slice(0, 1) }
function formatDate(value) { return value ? String(value).replace('T', ' ').slice(0, 16) : '-' }
onMounted(loadUsers)
</script>

<style scoped>
.page { max-width: 1320px; margin: 0 auto; }.page-heading { min-height: 52px; display: flex; align-items: end; justify-content: space-between; gap: 18px; }.section-label { margin-bottom: 7px; color: #6f8192; font-size: 12px; }h1 { color: #20364e; font-size: 24px; font-weight: 600; }.scope-note { color: #6f8192; font-size: 13px; }.filter-panel,.table-panel { margin-top: 24px; border: 1px solid #e4eaf0; background: #fff; }.filter-panel { display: flex; flex-wrap: wrap; align-items: end; gap: 16px; padding: 20px; }.filter-field { min-width: 170px; display: flex; flex-direction: column; gap: 8px; color: #6f8192; font-size: 12px; }.filter-keyword { min-width: 280px; }input,select { height: 36px; min-width: 170px; padding: 0 10px; border: 1px solid #d7e1e9; border-radius: 3px; background: #fff; color: #20364e; font: inherit; outline: none; }input:focus,select:focus { border-color: #1766a6; }button { font: inherit; cursor: pointer; }.filter-actions,.pagination>div { display: flex; gap: 8px; }.primary-button,.secondary-button { min-height: 36px; padding: 0 15px; border-radius: 3px; }.primary-button { border: 1px solid #1766a6; background: #1766a6; color: #fff; }.secondary-button { border: 1px solid #cbd8e2; background: #fff; color: #1766a6; }.primary-button:disabled,.secondary-button:disabled { cursor: not-allowed; opacity: .6; }.table-heading { display: flex; align-items: center; justify-content: space-between; padding: 20px; border-bottom: 1px solid #e4eaf0; }.table-heading h2,.drawer-heading h2 { color: #20364e; font-size: 16px; font-weight: 600; }.total-count { color: #6f8192; font-size: 12px; }.table-scroll { overflow-x: auto; }table { width: 100%; min-width: 820px; border-collapse: collapse; font-size: 13px; }th,td { height: 58px; padding: 8px 20px; border-bottom: 1px solid #edf1f4; text-align: left; white-space: nowrap; }th { height: 42px; color: #6f8192; background: #fbfcfd; font-size: 12px; font-weight: 500; }tr:last-child td { border-bottom: 0; }td strong { color: #20364e; font-weight: 600; }.status { display: inline-block; padding: 4px 8px; font-size: 12px; }.status-on { color: #2f8a60; background: #edf8f2; }.status-off { color: #9a6b2f; background: #fff7e9; }.action-column { text-align: right; }.link-button { margin-left: 12px; padding: 0; border: 0; background: transparent; color: #1766a6; }.link-button:disabled { cursor: not-allowed; color: #aebbc5; }.danger-link { color: #c4544e; }.action-message { padding: 10px 20px; border-bottom: 1px solid #e4eaf0; font-size: 13px; }.action-message.success { color: #2f8a60; background: #f2fbf5; }.action-message.error { color: #c4544e; background: #fff5f4; }.state-panel { min-height: 190px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 14px; padding: 24px; color: #6f8192; font-size: 14px; }.state-error { color: #c4544e; }.pagination { display: flex; align-items: center; justify-content: space-between; padding: 16px 20px; border-top: 1px solid #e4eaf0; color: #6f8192; font-size: 12px; }.drawer-mask { position: fixed; z-index: 40; inset: 0; display: flex; justify-content: flex-end; background: rgba(32,54,78,.3); }.drawer { width: min(500px,100%); height: 100%; display: flex; flex-direction: column; overflow-y: auto; background: #fff; box-shadow: -8px 0 24px rgba(18,58,99,.16); }.drawer-heading { display: flex; align-items: center; justify-content: space-between; padding: 22px 24px; border-bottom: 1px solid #e4eaf0; }.drawer-heading p { margin-bottom: 6px; color: #6f8192; font-size: 12px; }.close-button { padding: 0; border: 0; background: transparent; color: #6f8192; font-size: 26px; line-height: 1; }.user-summary { display: flex; align-items: center; gap: 15px; padding: 24px; border-bottom: 1px solid #edf1f4; }.user-summary>span { width: 54px; height: 54px; display: grid; place-items: center; flex: 0 0 54px; border-radius: 50%; color: #fff; background: #7892a8; font-size: 21px; }.user-summary h3 { color: #20364e; font-size: 18px; }.user-summary p { margin-top: 6px; color: #6f8192; font-size: 12px; }.detail-list { flex: 1; padding: 8px 24px 20px; }.detail-list>div { display: grid; grid-template-columns: 92px 1fr; gap: 18px; padding: 16px 0; border-bottom: 1px solid #edf1f4; font-size: 13px; }.detail-list>div:last-child { border-bottom: 0; }dt { color: #6f8192; }dd { margin: 0; color: #20364e; word-break: break-word; }.drawer-actions { display: flex; justify-content: flex-end; gap: 10px; padding: 18px 24px; border-top: 1px solid #e4eaf0; background: #fff; }
@media(max-width:560px){.page-heading { align-items: flex-start; flex-direction: column; }.filter-panel { align-items: stretch; flex-direction: column; }.filter-field,.filter-keyword,input,select { min-width: 0; width: 100%; }.filter-actions button { flex: 1; }.table-panel { margin-top: 18px; }.drawer-heading,.user-summary,.detail-list { padding-right: 18px; padding-left: 18px; }.drawer-actions { padding: 16px 18px; }}
</style>
